    {
      "path": "src/index.ts",
      "content": "/**\n * AgentTeams for DeepSeek Harness.\n *\n * A host-plane plugin that registers the `agent_teams_*` tools and one usage\n * agent-scoped usage section. Each session keeps a stable tool set and core\n * instructions. Existing business tools cover the complete team lifecycle.\n * After installation any session can\n * run multi-agent teamwork through natural language (e.g. \"use AgentTeams to research X\"):\n * the model creates a team (it becomes the captain), spawns members as\n * durable continuable subagents, breaks the goal into tasks with\n * dependencies, wakes members with messages, relays reports, and collects\n * results.\n *\n * Installation (bundle): `dsh plugin --profile <name> add @nanmicoder/dsh-agent-teams`\n * (or a local path). The bundle patch mounts this plugin row into the host\n * composition; the tools register into the shared `tools` registry and the\n * usage section into the global system prompt, so the plugin needs no realm.\n *\n * @module dsh-agent-teams\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport z from '@deepseek-ai/schemastery'\nimport { createUserMessage } from '@deepseek-ai/dsh-llm'\n// Declaration merges make ctx.subagents and ctx.systemPrompt visible.\nimport type {} from '@deepseek-ai/dsh-subagent'\nimport type {} from '@deepseek-ai/dsh-system-prompt'\nimport type { WorkspaceRegistry } from '@deepseek-ai/dsh-workspace'\nimport {\n  haltTeamWork,\n  stagedPlanApprovedContext,\n  registerAgentTeamsTools,\n  type StagedPlanMutation,\n  type ToolsConfig,\n} from './tools.ts'\nimport { installAgentTeamsGestureBoundary, registerAgentTeamsCommand } from './command.ts'\nimport { readFile } from 'node:fs/promises'\nimport { join } from 'node:path'\nimport { fileURLToPath } from 'node:url'\nimport { collectArchivedTeamsActivity, collectTeamsActivity } from './snapshot.ts'\nimport { findTeamByCaptain } from './state.ts'\nimport { leadIdentityOfAsync } from './lineage.ts'\nimport { formatProfilesForPrompt, type TeamProfileConfig } from './profiles.ts'\nimport { parseToolPolicies, type MemberToolPolicy } from './tool-policies.ts'\nimport { installTeamCapabilities } from './capabilities.ts'\nimport { agentTeamsSource, observedSessionFormatVersion } from './harness-compat.ts'\nimport { TEAM_TOOL_NAMES } from './tool-names.ts'\n\nimport { authenticatedWebRoutes, readJsonRequest, RequestBodyError, type BrowserRequestGate, type WebRouteHost } from './web-routes.ts'\n\n/** Web-server service key candidates, newest first. */\nconst WEB_SERVER_KEYS = ['webServer', 'httpServer'] as const\n/** Workspace registry service key candidates, newest first. */\nconst WORKSPACE_KEYS = ['workspaceRegistry', 'workspace'] as const\n\nexport const name = 'agent-teams'\nexport const inject = ['tools', 'llm', 'subagents', 'systemPrompt', 'agents']\n\n/** Plugin configuration. */\nexport interface Config {\n  /**\n   * State directory name under the captain's workspace; team state lives at\n   * `<workspace>/<stateDir>/<teamId>/` (default `.agent-teams`).\n   */\n  stateDir?: string\n  /** `ctx.subagents` provider used to spawn members; must support continuable children and personas (default `spawn`). */\n  memberProvider?: string\n  /**\n   * Optional model override applied to every member. The id is used verbatim.\n   * When the captain's provider does not advertise it, the provider that does\n   * is resolved from the live catalogs (only if exactly one advertises it);\n   * set `memberLlmProvider` to name the owner explicitly instead.\n   */\n  memberModel?: string\n  /**\n   * LLM provider route that owns `memberModel`. Set this when the member model\n   * is served by a different provider than the captain's session; without it\n   * the captain's provider is only used if it actually advertises the model,\n   * and an ambiguous or unowned model fails with the provider catalogs instead\n   * of being silently paired with the captain's route (issue #189).\n   * Distinct from `memberProvider`, which is the subagent runtime backend.\n   */\n  memberLlmProvider?: string\n  /** Prompt injected into member personas and automatic task assignments. */\n  executionPrompt?: string\n  /** Plugin-wide fallback route for unavailable member models. */\n  fallback?: import('./profiles.ts').TeamModelFallbackConfig\n  /** Member delegation depth cap (default `0`; `0` forbids delegation entirely). */\n  memberMaxDepth?: number\n  /** Team size cap in members (default `8`). */\n  maxMembers?: number\n  /** Named multi-role team profiles. */\n  profiles?: Record<string, TeamProfileConfig>\n  /**\n   * Reusable per-member tool policies declared by the deployment owner (#59),\n   * keyed by policy id. A member selects one by id (`tool_policy` on\n   * `agent_teams_add_member`, a plan member, or a profile member row); the\n   * Captain model can select an existing policy but never submit raw lists.\n   * `allow` keeps only the named global tools (the four coordination tools are\n   * always added); `deny` removes the named global tools. Captain-only tools\n   * stay denied either way.\n   */\n  toolPolicies?: Record<string, MemberToolPolicy>\n  /** Prompt-section order for the usage policy (default `117`, after delegation policy). */\n  promptSectionOrder?: number\n  /**\n   * Register the deterministic `/agent-teams` activation surfaces (the\n   * closed-namespace slash command and the plain-text gesture boundary).\n   * Disable to keep the natural-language trigger as the only entry point.\n   */\n  slashCommand?: boolean\n}\n\n// `z.object()` has an implicit `{}` default in Schemastery.  Fallback routes\n// are optional, so model absence explicitly; otherwise a missing route is\n// validated as an empty object and fails on the required provider/model keys.\nconst fallbackRouteConfig = z.union([\n  z.object({ provider: z.string().required(), model: z.string().required() }),\n  z.const(undefined),\n])\n\n// Same Schemastery defaulting trap for a tool policy: an `allow`-only policy\n// would materialize `deny: []` and fail a `.min(1)` on an absent list. Model\n// each accepted combination explicitly, so a policy that declares only one\n// side stays valid while an empty side is still rejected.\nconst toolPolicyConfig = z.union([\n  z.object({ allow: z.array(z.string()).min(1).required(), deny: z.const(undefined) }),\n  z.object({ allow: z.const(undefined), deny: z.array(z.string()).min(1).required() }),\n  z.object({ allow: z.array(z.string()).min(1).required(), deny: z.array(z.string()).min(1).required() }),\n])\n\nexport const Config: z<Config> = z.object({\n  stateDir: z.string().default('.agent-teams'),\n  memberProvider: z.string().default('spawn'),\n  memberModel: z.string(),\n  memberLlmProvider: z.string(),\n  executionPrompt: z.string(),\n  fallback: fallbackRouteConfig,\n  profiles: z.dict(z.object({\n    description: z.string(),\n    protocol: z.string(),\n    executionPrompt: z.string(),\n    fallback: fallbackRouteConfig,\n    members: z.array(z.object({\n      name: z.string().required(),\n      role: z.string(),\n      provider: z.string(),\n      model: z.string(),\n      reasoning_effort: z.string(),\n      executionPrompt: z.string(),\n      fallback: fallbackRouteConfig,\n      // Owner-declared tool-policy id this profile member selects (#59).\n      tool_policy: z.string(),\n    })).min(1).required(),\n    taskPlanning: z.union([z.const('captain'), z.const('seed')]),\n    reviewPolicy: z.object({\n      requirementsMinRounds: z.natural().min(1),\n      requirementsMaxRounds: z.natural().min(1),\n      codeMaxRounds: z.natural().min(1),\n      maxRepairAttempts: z.natural().min(1),\n      requiredReviewers: z.array(z.string()),\n    }),\n    tasks: z.array(z.object({\n      id: z.string().required(),\n      subject: z.string().required(),\n      description: z.string(),\n      assignee: z.string(),\n      dependencies: z.array(z.string()),\n    })),\n  })).default({}),\n  toolPolicies: z.dict(toolPolicyConfig).default({}),\n  memberMaxDepth: z.natural().default(0),\n  maxMembers: z.natural().min(1).default(8),\n  promptSectionOrder: z.natural().default(117),\n  slashCommand: z.boolean().default(true),\n})\n\n/** The model-facing usage policy: when and how to drive AgentTeams. */\nexport function usageSectionText(toolNames: string, profilesText = ''): string {\n  return `AgentTeams captain protocol:\n1. Inspect current team state when needed, using agent_teams_status. Continue existing work without duplicating its roster/tasks. Create only when no current team exists, with the user's goal as description and approval=\"required\"; automatic approval requires an explicit request to run immediately. Staged plans never spawn or schedule work.\n2. Add each needed role once; members inherit your model route unless another is requested/needed. A requested profile goes to create({profile}); it supplies its roster. Seed profiles also supply tasks; captain-planning profiles require your DAG. Do not duplicate either. A member may also select one owner-declared tool policy by id (tool_policy on add_member, a plan member, or a profile member): it is the only way to change which global tools that member sees and may invoke, and you can never pass raw allow/deny lists.\n3. Build the complete smallest useful DAG while staged. For an ordinary research/audit plan, pass the roster and dependency graph together in create({plan:{members,tasks}}) to avoid repeated setup rounds. Every task needs a subject; pass kind and assignee explicitly when the plan specifies them. Titles, descriptions and member roles do not set these fields. Dependencies represent prerequisites. Give every required contributor a task or explicit message. Present the plan and end your turn for review; never approve in that planning turn. Approve only after a later explicit user approval or the Web action.\n4. Respect Web approve/return/discard control messages. On return, ask what to change before editing; after the answer, use one atomic agent_teams_edit_plan batch (edit downstream references before removals), summarize and await review again. Never inspect or edit .agent-teams state files or plugin source code to revise plans. Discard does not authorize a replacement.\n5. The scheduler dispatches ready tasks after approval. Delegate; do not duplicate slow work or send messages merely to start a stage. Handle reports/user work, then yield when waiting is all that remains: reports wake you automatically. Use status after a delivery or user request, never busy-poll or wait for unassigned members.\n6. Tasks carry attempt_id capabilities. Use the current attempt_id; stale means ownership changed. Pause members only on explicit request; later guidance via send_message continues that same attempt. Retry, transfer or take over through reassign_task first; it revokes the old attempt and waits for quiescence. Prefer a member. Captain implementation/review takeover requires a user request. Every takeover is one ready task at a time, finished in this turn; never yield with captain-owned work open.\n7. In a running team, correct never-started pending tasks with edit_plan update_task; preserve dependency and ownership contracts instead of cancelling and recreating the graph. A captain can cancel a never-started pending task directly. Active attempts still require reassign_task. Quality kinds (requirements, implementation, verification, review, repair, integration) require objective + acceptance; implementation/repair also require inScope + verify. Derive paths/commands from the workspace/profile, never assume src/ or pnpm test. Review/requirements complete only with verdict=pass; needs_revision/reject fail with findings. Never approve your own implementation or ask for a deliberate failure. When a quality contract itself is wrong (a verify command that cannot pass, an inScope that forbids the file the objective requires), fix it with agent_teams_amend_task — captain-only, non-terminal tasks only, frozen after a passing review, and every amendment is recorded in the task's revisions ledger — instead of letting the worker dead-lock or game the gate.\n8. When full quality mode is requested: requirements → implementation → verification → review → integration. Plan the entire DAG while staged, including implementation before requirements finishes and integration depending on review round 1. Failed review automatically adds repair + next review and rewires pending downstream gates. Do not recreate this loop, omit integration or depend on a failed task. Review acceptance judges the latest implementation. Do not put smoke-test scripts into task instructions.\n9. Halted means the user stopped work (including the captain turn). Resume only on a later explicit user request with a reason, via agent_teams_resume or create_task({resume:true,resumeReason}); creating tasks alone never resumes. Escalated means the review loop hit its limit, not a halt. Deployment requires explicit user confirmation.\n10. Wait for all required tasks to be terminal and members idle/ready, present results, then delete/archive unless the user wants to continue. Never discard unfinished work without authorization.\nTools: ${toolNames}${profilesText === '' ? '' : `\\n\\n${profilesText}`}`\n}\n\nexport function apply(ctx: Context, config: Config): void {\n  const resolved: ToolsConfig = {\n    stateDir: config.stateDir ?? '.agent-teams',\n    memberProvider: config.memberProvider ?? 'spawn',\n    memberModel: config.memberModel,\n    memberLlmProvider: config.memberLlmProvider,\n    executionPrompt: config.executionPrompt,\n    fallback: config.fallback,\n    memberMaxDepth: config.memberMaxDepth ?? 0,\n    maxMembers: config.maxMembers ?? 8,\n    profiles: config.profiles ?? {},\n    // Owner configuration is validated once, at mount: an empty or malformed\n    // policy must never reach a member creation path.\n    toolPolicies: parseToolPolicies(config.toolPolicies),\n  }\n\n  // Provider registration is a sibling plugin's effect (`subagent-spawn` /\n  // `subagent-fork` rows), which can land after this mount under the Loader's\n  // concurrent activation — so capability validation happens at the first\n  // member spawn (`spawnMember`), the earliest point the provider list is\n  // settled, rather than here.\n\n  const agentTeamsRuntime = registerAgentTeamsTools(ctx, resolved)\n  installTeamCapabilities(ctx, {\n    stateDir: resolved.stateDir,\n    isPendingMember: agentTeamsRuntime.isPendingMember,\n    order: config.promptSectionOrder,\n    // Keep the bounded profile directory available without extra tool calls.\n    // installTeamCapabilities snapshots this once; no business state rewrites it.\n    captainPrompt: () => usageSectionText(TEAM_TOOL_NAMES.join(', '), formatProfilesForPrompt(config.profiles)),\n  })\n\n  // Deterministic activation surfaces: the closed-namespace `/agent-teams`\n  // host command (surfaces in the Web GUI slash menu via the Harness\n  // ui-commands client) and the plain-text gesture boundary for surfaces\n  // without command adjudication (headless CLI). Both default on; a profile\n  // can disable them to keep the natural-language trigger exclusive.\n  //\n  // `commands` is registered lazily (not a required inject): it ships in the\n  // base bundle of every standard profile, but a minimal composition that\n  // omits the command registry keeps the plugin fully functional — the fiber\n  // never pends on it and simply never gains the slash command.\n  if (config.slashCommand ?? true) {\n    ctx.inject(['commands'], (commandCtx) => {\n      registerAgentTeamsCommand(commandCtx, () => config.profiles ?? {})\n    })\n    installAgentTeamsGestureBoundary(ctx, () => config.profiles ?? {})\n  }\n\n  // The activity panel data/artwork routes need the Web server and the\n  // workspace registry, which headless profiles do not mount; under\n  // concurrent activation they may also bind after this plugin. Register the\n  // routes lazily: try now, then on each service binding event. In a webless\n  // profile the plugin stays tool-only and never blocks boot.\n  let webRegistered = false\n  const registerWebSurface = (): void => {\n    if (webRegistered) return\n    const rawWebServer = (ctx.get(WEB_SERVER_KEYS[0]) ?? ctx.get(WEB_SERVER_KEYS[1])) as WebRouteHost | undefined\n    const workspaceRegistry = (ctx.get(WORKSPACE_KEYS[0]) ?? ctx.get(WORKSPACE_KEYS[1])) as WorkspaceRegistry | undefined\n    if (rawWebServer === undefined || workspaceRegistry === undefined) return\n    const webServer = authenticatedWebRoutes(rawWebServer, () => ctx.get('connection') as BrowserRequestGate | undefined)\n    webRegistered = true\n\n    // Activity panel data route: the browser floater polls this for team\n    // snapshots (disk truth + live subagent activity). Mirrors the Claude\n    // Code desktop watcher's server-side snapshot pattern.\n    ctx.effect(() => webServer.register({\n    kind: 'exact',\n    path: '/plugins/dsh-agent-teams/state',\n    handler: async (req, res) => {\n      const url = new URL(req.url ?? '/', 'http://x')\n      const roots = workspaceRegistry.list().map((workspace) => ({\n        workspace: workspace.title,\n        // The panel audits the same current bytes as agent_teams_status, so it\n        // cannot advertise a passing gate over a changed revision (#161).\n        workspacePath: workspace.path,\n        stateRoot: join(workspace.path, resolved.stateDir),\n      }))\n      // ?archived=1 serves teams moved to archive/ (post-delete review).\n      const snapshots = url.searchParams.get('archived') === '1'\n        ? await collectArchivedTeamsActivity(ctx, roots)\n        : await collectTeamsActivity(ctx, roots)\n      const body = JSON.stringify({ teams: snapshots })\n      res.writeHead(200, {\n        'content-type': 'application/json; charset=utf-8',\n        'cache-control': 'no-store',\n      })\n      res.end(body)\n    },\n  }), 'agent-teams: activity route')\n\n    ctx.effect(() => webServer.register({\n      kind: 'exact',\n      path: '/plugins/dsh-agent-teams/halt',\n      handler: async (req, res) => {\n        if (req.method !== 'POST') {\n          res.writeHead(405, { allow: 'POST', 'cache-control': 'no-store' })\n          res.end()\n          return\n        }\n        let payload: Record<string, unknown>\n        try {\n          payload = await readJsonRequest(req)\n        } catch (error: unknown) {\n          res.writeHead(error instanceof RequestBodyError ? error.status : 400, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n          res.end(JSON.stringify({ error: error instanceof Error ? error.message : 'invalid request body' }))\n          return\n        }\n        const sessionId = typeof payload.sessionId === 'string' ? payload.sessionId.trim() : ''\n        const teamId = typeof payload.teamId === 'string' ? payload.teamId.trim() : ''\n        if (sessionId === '' || teamId === '') {\n          res.writeHead(400, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n          res.end(JSON.stringify({ error: 'sessionId and teamId are required' }))\n          return\n        }\n        const captain = ctx.agents.get(sessionId as import('@deepseek-ai/dsh-session').SessionId)\n        if (captain === undefined) {\n          res.writeHead(409, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n          res.end(JSON.stringify({ error: 'captain session is not attached' }))\n          return\n        }\n        const workspace = captain.session.header.cwd ?? process.cwd()\n        const stateRoot = join(workspace, resolved.stateDir)\n        const team = await findTeamByCaptain(stateRoot, captain.id, await leadIdentityOfAsync(ctx, captain.session))\n        if (team === undefined || team.id !== teamId) {\n          res.writeHead(404, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n          res.end(JSON.stringify({ error: 'team not found for this captain' }))\n          return\n        }\n        try {\n          const result = await haltTeamWork({\n            ctx,\n            stateRoot,\n            teamId,\n            captain,\n          })\n          res.writeHead(200, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n          res.end(JSON.stringify(result))\n        } catch (error: unknown) {\n          ctx.logger.warn(`agent-teams: halt failed for ${teamId}: ${String(error)}`)\n          res.writeHead(500, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n          res.end(JSON.stringify({ error: 'failed to stop the team' }))\n        }\n      },\n    }), 'agent-teams: halt route')\n\n    ctx.effect(() => webServer.register({\n      kind: 'exact',\n      path: '/plugins/dsh-agent-teams/plan',\n      handler: async (req, res) => {\n        if (req.method !== 'POST') {\n          res.writeHead(405, { allow: 'POST', 'cache-control': 'no-store' })\n          res.end()\n          return\n        }\n        let payload: Record<string, unknown>\n        try {\n          payload = await readJsonRequest(req)\n        } catch (error: unknown) {\n          res.writeHead(error instanceof RequestBodyError ? error.status : 400, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n          res.end(JSON.stringify({ error: error instanceof Error ? error.message : 'invalid request body' }))\n          return\n        }\n        const sessionId = typeof payload['sessionId'] === 'string' ? payload['sessionId'].trim() : ''\n        const teamId = typeof payload['teamId'] === 'string' ? payload['teamId'].trim() : ''\n        const action = typeof payload['action'] === 'string' ? payload['action'] : ''\n        if (sessionId === '' || teamId === '' || action === '') {\n          res.writeHead(400, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n          res.end(JSON.stringify({ error: 'sessionId, teamId, and action are required' }))\n          return\n        }\n        const captain = ctx.agents.get(sessionId as import('@deepseek-ai/dsh-session').SessionId)\n        if (captain === undefined) {\n          res.writeHead(409, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n          res.end(JSON.stringify({ error: 'captain session is not attached' }))\n          return\n        }\n        const workspace = captain.session.header.cwd ?? process.cwd()\n        const stateRoot = join(workspace, resolved.stateDir)\n        const team = await findTeamByCaptain(stateRoot, captain.id, await leadIdentityOfAsync(ctx, captain.session))\n        if (team === undefined || team.id !== teamId) {\n          res.writeHead(404, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n          res.end(JSON.stringify({ error: 'team not found for this captain' }))\n          return\n        }\n        try {\n          if (action === 'approve') {\n            const approved = await agentTeamsRuntime.approveStagedTeam(captain, teamId)\n            // The browser receives the HTTP result, so the model needs its own\n            // control message. steer wakes an idle captain or joins its next\n            // step; the tool approve path already returns to the model itself.\n            try {\n              captain.steer(createUserMessage({\n                content: [{ type: 'text', text: stagedPlanApprovedContext(team.name) }],\n                source: agentTeamsSource({ kind: 'agent-teams' }, observedSessionFormatVersion(captain)),\n              }))\n            } catch (error) {\n              // Approval is already committed. Do not report a failed approval\n              // and invite a retry that could duplicate the user's action.\n              ctx.logger.warn(`agent-teams: approval notification failed for ${teamId}: ${String(error)}`)\n            }\n            res.writeHead(200, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n            res.end(JSON.stringify({ ok: true, phase: 'running', ...approved }))\n            return\n          }\n          if (action === 'continue') {\n            const continued = await agentTeamsRuntime.continueStagedPlanning(captain, teamId)\n            res.writeHead(200, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n            res.end(JSON.stringify({ ok: true, phase: 'staged', review: 'awaiting_feedback', ...continued }))\n            return\n          }\n          if (action === 'discard') {\n            const discarded = await agentTeamsRuntime.discardStagedTeam(captain, teamId)\n            res.writeHead(200, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n            res.end(JSON.stringify({ ok: true, phase: 'archived', ...discarded }))\n            return\n          }\n          const dependencies = Array.isArray(payload['dependencies'])\n            ? payload['dependencies'].filter((item): item is string => typeof item === 'string')\n            : []\n          let mutation: StagedPlanMutation\n          if (action === 'update_member') {\n            if (typeof payload['memberName'] !== 'string'\n              || typeof payload['provider'] !== 'string'\n              || typeof payload['model'] !== 'string') throw new Error('memberName, provider, and model are required')\n            mutation = {\n              action,\n              memberName: payload['memberName'],\n              provider: payload['provider'],\n              model: payload['model'],\n              ...typeof payload['role'] === 'string' || payload['role'] === null ? { role: payload['role'] as string | null } : {},\n              ...typeof payload['reasoningEffort'] === 'string' || payload['reasoningEffort'] === null\n                ? { reasoningEffort: payload['reasoningEffort'] as string | null }\n                : {},\n              ...typeof payload['executionPrompt'] === 'string' || payload['executionPrompt'] === null\n                ? { executionPrompt: payload['executionPrompt'] as string | null }\n                : {},\n              ...typeof payload['tool_policy'] === 'string' ? { toolPolicy: payload['tool_policy'] } : {},\n            }\n          } else if (action === 'update_task') {\n            if (typeof payload['taskId'] !== 'string' || typeof payload['subject'] !== 'string') {\n              throw new Error('taskId and subject are required')\n            }\n            mutation = {\n              action,\n              taskId: payload['taskId'],\n              subject: payload['subject'],\n              dependencies,\n              ...typeof payload['description'] === 'string' || payload['description'] === null\n                ? { description: payload['description'] as string | null }\n                : {},\n              ...typeof payload['assignee'] === 'string' || payload['assignee'] === null\n                ? { assignee: payload['assignee'] as string | null }\n                : {},\n            }\n          } else if (action === 'add_task') {\n            if (typeof payload['subject'] !== 'string') throw new Error('subject is required')\n            mutation = {\n              action,\n              subject: payload['subject'],\n              dependencies,\n              ...typeof payload['description'] === 'string' || payload['description'] === null\n                ? { description: payload['description'] as string | null }\n                : {},\n              ...typeof payload['assignee'] === 'string' || payload['assignee'] === null\n                ? { assignee: payload['assignee'] as string | null }\n                : {},\n            }\n          } else if (action === 'remove_task') {\n            if (typeof payload['taskId'] !== 'string') throw new Error('taskId is required')\n            mutation = { action, taskId: payload['taskId'] }\n          } else {\n            throw new Error(`unknown plan action \"${action}\"`)\n          }\n          const updated = await agentTeamsRuntime.updateStagedPlan(captain, teamId, mutation)\n          res.writeHead(200, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n          res.end(JSON.stringify({ ok: true, phase: updated.phase, members: updated.members.length, tasks: updated.tasks.length }))\n        } catch (error: unknown) {\n          res.writeHead(409, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n          res.end(JSON.stringify({ error: error instanceof Error ? error.message : 'plan operation failed' }))\n        }\n      },\n    }), 'agent-teams: plan route')\n\n  // Whale mascot artwork: serve the packaged V2 role/action images to the\n  // activity panel. An explicit allowlist guards the route (no path\n  // traversal); the images ship with the bundle (files: assets/).\n  const artDir = fileURLToPath(new URL('../assets/agent-teams/', import.meta.url))\n  const ART_ALLOWLIST = new Set([\n    'team-lead-v2.png',\n    'member-researcher-v2.png', 'member-engineer-v2.png',\n    'member-qa-v2.png', 'member-designer-v2.png',\n    'member-security-v2.png', 'member-docs-v2.png',\n    'member-data-v2.png', 'member-operator-v2.png',\n    'action-working-v2.png', 'action-thinking-v2.png',\n    'action-reporting-v2.png', 'action-celebrating-v2.png',\n    'action-sleeping-v2.png', 'action-sending-v2.png',\n  ])\n    ctx.effect(() => webServer.register({\n      kind: 'prefix',\n      path: '/plugins/dsh-agent-teams/assets',\n    handler: async (req, res) => {\n      let name: string\n      try {\n        name = decodeURIComponent(new URL(req.url ?? '/', 'http://x').pathname.split('/').pop() ?? '')\n      } catch {\n        // Malformed percent-encoding: treat as an unknown asset, not a 400.\n        res.writeHead(404)\n        res.end()\n        return\n      }\n      if (!ART_ALLOWLIST.has(name)) {\n        res.writeHead(404)\n        res.end()\n        return\n      }\n      try {\n        const data = await readFile(join(artDir, name))\n        res.writeHead(200, {\n          'content-type': 'image/png',\n          'cache-control': 'public, max-age=86400',\n        })\n        res.end(data)\n      } catch (error: unknown) {\n        ctx.logger.warn(`agent-teams: artwork read failed for ${name}: ${String(error)}`)\n        res.writeHead(404)\n        res.end()\n      }\n      },\n    }), 'agent-teams: artwork route')\n  }\n\n  registerWebSurface()\n  ctx.on('internal/service', (name) => {\n    if (WEB_SERVER_KEYS.includes(name as (typeof WEB_SERVER_KEYS)[number])\n      || WORKSPACE_KEYS.includes(name as (typeof WORKSPACE_KEYS)[number])) {\n      registerWebSurface()\n    }\n  })\n}\n"
    },
    {
      "path": "src/scheduler.ts",
      "content": "/**\n * Event-driven shared task scheduler.\n *\n * Claude Code teammates keep polling the shared task list after a turn. DSH\n * continuable agents instead expose explicit idle/running edges, so this\n * scheduler closes the same loop without keeping a polling turn alive: every\n * idle edge and every task-graph mutation attempts one atomic claim and wakes\n * the selected durable member. A resident member that becomes idle while it\n * still owns an open attempt is parked: only an explicit captain reassignment\n * may rotate that capability. Automatic retry is reserved for cold recovery,\n * when this process has not observed the durable owner settle its open attempt.\n * @module dsh-agent-teams/scheduler\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { Agent, AgentStatus } from '@deepseek-ai/dsh-agent'\nimport type { SessionId } from '@deepseek-ai/dsh-session'\nimport { join } from 'node:path'\nimport { deliverToMember } from './members.ts'\nimport { isCurrentMail, mailboxPrompt } from './mailbox.ts'\nimport {\n  markMailboxDelivered,\n  discardMailboxMessages,\n  beginTaskAttempt,\n  CAPTAIN_KEY,\n  claimMailboxDelivery,\n  findTeamByParticipant,\n  invalidateTaskAttempt,\n  readTeam,\n  readPendingMailbox,\n  releaseMailboxDelivery,\n  unsatisfiedDependencies,\n  withTeamLock,\n  writeTeam,\n} from './state.ts'\nimport { contractStaleness, isVerdictKind, taskKindOf, verdictScopePatterns } from './quality-gates.ts'\nimport { digestWorkspacePaths, snapshotWorkspacePaths } from './artifacts.ts'\nimport type { TeamMember, TeamState, TeamTask } from './types.ts'\n\n/** Per-dependency output cap in the assignment prompt. */\nexport const DEPENDENCY_OUTPUT_MAX_CHARS = 2_000\n/** Combined dependency-output budget in the assignment prompt. */\nexport const DEPENDENCY_OUTPUTS_TOTAL_MAX_CHARS = 12_000\n\nexport interface SchedulerConfig {\n  readonly stateDir: string\n  readonly executionPrompt?: string\n  readonly dispatch?: (captain: Agent, teamId: string, memberName: string, text: string, signal: AbortSignal, mode: 'queue' | 'steer', attemptId?: string) => Promise<boolean>\n}\n\nexport interface TeamScheduler {\n  /** Try to give every genuinely idle/ready member one unit of ready work. */\n  kickTeam(workspace: string, teamId: string, captain?: Agent): Promise<void>\n  /** Try to flush fallback mail or give one member one ready task. */\n  kickMember(workspace: string, teamId: string, memberName: string, captain?: Agent): Promise<void>\n}\n\n/** One completed recursive dependency shown to the assignee. */\nexport interface DependencyOutput {\n  readonly id: string\n  readonly subject: string\n  readonly profileSeedId?: string\n  readonly output?: string\n}\n\nexport interface DispatchTicket {\n  readonly taskId: string\n  readonly memberName: string\n  readonly memberId: string\n  readonly attempt: number\n  readonly attemptId: string\n  readonly previousAssignee?: string\n  /** True when this ticket rotates an unobserved durable open attempt. */\n  readonly recoveredOwned: boolean\n  /** Original task generation, used to restore a failed automatic recovery. */\n  readonly previousStatus?: 'claimed' | 'in_progress'\n  readonly previousAttempt?: number\n  readonly previousAttemptId?: string\n  readonly previousResult?: Pick<TeamTask, 'output' | 'verdict' | 'findings' | 'changedPaths' | 'acceptanceResults' | 'commandsRun'>\n  readonly subject: string\n  readonly description?: string\n  readonly teamDescription?: string\n  readonly profileProtocol?: string\n  readonly profileSeedId?: string\n  readonly dependencyOutputs: readonly DependencyOutput[]\n  readonly executionPrompt?: string\n  readonly kind?: string\n  readonly round?: number\n  readonly objective?: string\n  readonly inScope?: readonly string[]\n  readonly outOfScope?: readonly string[]\n  readonly acceptance?: readonly string[]\n  readonly verify?: readonly string[]\n  readonly reviewedTaskId?: string\n  readonly findingSourceTaskIds?: readonly string[]\n}\n\nfunction taskProfileSeedId(task: TeamTask): string | undefined {\n  const seed = task.profileSeedId?.trim()\n  return seed === undefined || seed === '' ? undefined : seed\n}\n\nfunction teamProfileProtocol(team: TeamState): string | undefined {\n  return team.profile?.protocol\n}\n\n/**\n * Recursively collect `status=completed` ancestors of `taskId` in topological\n * order (dependencies before dependents). Cycles stop that branch only.\n */\nexport function collectCompletedDependencyOutputs(\n  tasks: readonly TeamTask[],\n  taskId: string,\n  warn?: (message: string) => void,\n): DependencyOutput[] {\n  const byId = new Map(tasks.map(task => [task.id, task]))\n  const visiting = new Set<string>()\n  const visited = new Set<string>()\n  const ordered: TeamTask[] = []\n\n  const walk = (id: string): void => {\n    if (visiting.has(id)) {\n      warn?.(`agent-teams: dependency cycle involving \"${id}\" while collecting outputs; stopping this branch`)\n      return\n    }\n    if (visited.has(id)) return\n    visiting.add(id)\n    const task = byId.get(id)\n    if (task !== undefined) {\n      for (const dependency of task.dependencies) walk(dependency)\n      if (id !== taskId) ordered.push(task)\n    }\n    visiting.delete(id)\n    visited.add(id)\n  }\n\n  walk(taskId)\n  return ordered\n    .filter(task => task.status === 'completed')\n    .map((task) => {\n      const profileSeedId = taskProfileSeedId(task)\n      return {\n        id: task.id,\n        subject: task.subject,\n        ...profileSeedId === undefined ? {} : { profileSeedId },\n        ...task.output === undefined ? {} : { output: task.output },\n      }\n    })\n}\n\n/** Format completed-dependency outputs with per-item and total truncation. */\nexport function formatDependencyOutputs(items: readonly DependencyOutput[]): string {\n  if (items.length === 0) return '(none)'\n  const formatted = items.map((item) => {\n    const seed = item.profileSeedId === undefined ? '' : ` [${item.profileSeedId}]`\n    const raw = item.output === undefined || item.output === ''\n      ? '(no output recorded)'\n      : item.output\n    const truncated = raw.length > DEPENDENCY_OUTPUT_MAX_CHARS\n    const body = truncated ? `${raw.slice(0, DEPENDENCY_OUTPUT_MAX_CHARS)} [truncated]` : raw\n    return `- ${item.id}${seed} ${item.subject}:\\n  ${body}`\n  })\n  let selected = formatted\n  while (selected.length > 1 && selected.join('\\n').length > DEPENDENCY_OUTPUTS_TOTAL_MAX_CHARS) {\n    selected = selected.slice(1)\n  }\n  const last = selected[0]\n  if (selected.length === 1 && last !== undefined && last.length > DEPENDENCY_OUTPUTS_TOTAL_MAX_CHARS) {\n    selected = [`${last.slice(0, DEPENDENCY_OUTPUTS_TOTAL_MAX_CHARS)} [truncated]`]\n  }\n  return selected.join('\\n')\n}\n\nfunction stateRootOf(workspace: string, config: SchedulerConfig): string {\n  return join(workspace, config.stateDir)\n}\n\nfunction teamLockKey(stateRoot: string, teamId: string): string {\n  return `team:${stateRoot}:${teamId}`\n}\n\nfunction liveCaptain(ctx: Context, captainSessionId: string, supplied?: Agent): Agent | undefined {\n  if (supplied !== undefined && supplied.id === captainSessionId) return supplied\n  return ctx.agents.get(captainSessionId as SessionId)\n}\n\nfunction liveMember(ctx: Context, member: TeamMember): Agent | undefined {\n  return ctx.agents.get(member.id as SessionId)\n}\n\nfunction isMemberAvailable(ctx: Context, member: TeamMember): boolean {\n  if (member.stopping === true) return false\n  const live = liveMember(ctx, member)\n  return live === undefined || live.status === 'idle'\n}\n\nfunction ownedOpenTask(tasks: readonly TeamTask[], memberName: string): TeamTask | undefined {\n  return tasks.find(task => task.assignee === memberName\n    && (task.status === 'claimed' || task.status === 'in_progress'))\n}\n\nfunction nextReadyTask(tasks: readonly TeamTask[], memberName: string): TeamTask | undefined {\n  const ready = tasks.filter(task => task.status === 'pending'\n    && task.reassigning !== true\n    && unsatisfiedDependencies([...tasks], task.dependencies).length === 0)\n  return ready.find(task => task.assignee === memberName)\n    ?? ready.find(task => task.assignee === undefined)\n}\n\nexport function assignmentPrompt(\n  ticket: DispatchTicket,\n  stateDir: string,\n  teamId: string,\n  workOrderWarnings: readonly string[] = [],\n): string {\n  const description = ticket.description === undefined ? '' : `\\n\\n${ticket.description}`\n  const seed = ticket.profileSeedId === undefined ? '' : ` [${ticket.profileSeedId}]`\n  const goal = ticket.teamDescription?.trim() || '(not provided)'\n  const protocol = ticket.profileProtocol?.trim() || '(none)'\n  const executionPrompt = ticket.executionPrompt?.trim()\n  const kind = ticket.kind?.trim() || 'work'\n  const staleWorkOrder = workOrderWarnings.length === 0\n    ? ''\n    : `\\nBefore you edit anything: this auto-generated work order was derived from a workspace that has since changed.\\n${workOrderWarnings.map((warning) => `- ${warning}`).join('\\n')}\\nRe-read the cited files first, locate the code by content anchor rather than by any position, and report a blocker instead of editing a target that no longer exists.\\n`\n  const contract = [\n    `Kind: ${kind}${ticket.round === undefined ? '' : ` (round ${ticket.round})`}`,\n    ticket.objective === undefined || ticket.objective === '' ? '' : `Objective: ${ticket.objective}`,\n    ticket.inScope === undefined || ticket.inScope.length === 0 ? '' : `In scope: ${ticket.inScope.join(', ')}`,\n    ticket.outOfScope === undefined || ticket.outOfScope.length === 0 ? '' : `Out of scope: ${ticket.outOfScope.join(', ')}`,\n    ticket.acceptance === undefined || ticket.acceptance.length === 0 ? '' : `Acceptance: ${ticket.acceptance.join('; ')}`,\n    ticket.verify === undefined || ticket.verify.length === 0 ? '' : `Verify: ${ticket.verify.join('; ')}`,\n    ticket.reviewedTaskId === undefined ? '' : `Reviewed task: ${ticket.reviewedTaskId}`,\n    ticket.findingSourceTaskIds === undefined || ticket.findingSourceTaskIds.length === 0 ? '' : `Fixes findings of: ${ticket.findingSourceTaskIds.join(', ')}`,\n  ].filter((line) => line !== '').join('\\n')\n  const structuredCompletion = ['implementation', 'repair', 'verification', 'integration'].includes(kind)\n    ? `\nStructured completion payload (keep these arrays in contract order):\nacceptanceResults: ${JSON.stringify((ticket.acceptance ?? []).map((criterion) => ({ criterion, status: 'passed', evidence: '<what proved it>' })))}\ncommandsRun: ${JSON.stringify((ticket.verify ?? []).map((command) => ({ command, status: 'passed', exitCode: 0, evidence: '<observed result>' })))}\n${kind === 'implementation' || kind === 'repair' ? 'changedPaths: list the actual workspace-relative POSIX paths you changed.\\n' : ''}`\n    : ''\n  return `AgentTeams automatic task assignment from the shared task list.\n\nYou are executing as configured member \"${ticket.memberName}\".\nDo not start a teammate's assigned task.\n\nTeam goal:\n${goal}\n\nProfile protocol:\n${protocol}\n${executionPrompt === undefined || executionPrompt === '' ? '' : `\nExecution guidance:\n${executionPrompt}\n`}\nCompleted dependency results:\n${formatDependencyOutputs(ticket.dependencyOutputs)}\n\nTask: ${ticket.taskId}${seed} — ${ticket.subject}${description}\n${staleWorkOrder}${contract === '' ? '' : `\\nContract:\\n${contract}\\n`}\n${structuredCompletion}\nAttempt: ${ticket.attempt}\nAttempt id: ${ticket.attemptId}\n\nCall agent_teams_claim_task for ${ticket.taskId}; it will return this same attempt_id. Include attempt_id=${ticket.attemptId} in every agent_teams_update_task call. If it is rejected as stale, stop work because the task was reassigned. claimed cannot jump to completed. Mark in_progress first, then completed or failed. Include attempt_id on every update. Then send_message to captain with source_task_id and source_attempt_id and become idle.\nWhen finishing: use status=completed only when the task's success criteria are satisfied; use status=failed when blocking findings or validation failures mean downstream work must not proceed; include a concise output in either case. Quality kinds must submit structured fields: review/requirements need verdict=pass to complete (needs_revision/reject must fail with findings); implementation/repair/verification/integration need acceptanceResults and commandsRun, while implementation/repair also need in-scope changedPaths. Use status values \"passed\" or \"failed\" inside those arrays. After the work and verification finish, call agent_teams_update_task immediately; do not wait for captain confirmation and do not continue exploring. Do not approve your own implementation. Mail is not a formal next review. Completed work must not be repeated to attach late evidence: call update_task on the original task with its attempt_id and acceptanceResults/commandsRun/evidence_note; supplements are append-only and cannot change its verdict. Treat the dependency results above as source material. Do not ignore them. Work only this task and only its in-scope paths in this turn.\n\nState policy: ${stateDir}/${teamId}/ is read-only diagnostics; mutate team state only through agent_teams_* tools.`\n}\n\n/** Install one scheduler and its member activity observer. */\nexport function installTeamScheduler(ctx: Context, config: SchedulerConfig): TeamScheduler {\n  const memberQueues = new Map<string, Promise<unknown>>()\n  // An idle edge in this process proves that the resident member ended its\n  // turn while the current attempt was still open. Remember that capability\n  // even after Harness disposes the continuable AgentHandle: later status or\n  // graph kicks must keep it parked. A cold process starts with an empty map,\n  // so durable open attempts are still recovered after restart.\n  const parkedAttempts = new Map<string, string>()\n\n  const memberQueueKey = (stateRoot: string, teamId: string, memberName: string): string => (\n    `${stateRoot}\\u0000${teamId}\\u0000${memberName}`\n  )\n\n  const serializeMember = async <T>(key: string, operation: () => Promise<T>): Promise<T> => {\n    const previous = memberQueues.get(key) ?? Promise.resolve()\n    let release!: () => void\n    const gate = new Promise<void>((resolve) => { release = resolve })\n    const tail = previous.then(() => gate)\n    memberQueues.set(key, tail)\n    await previous\n    try {\n      return await operation()\n    } finally {\n      release()\n      if (memberQueues.get(key) === tail) memberQueues.delete(key)\n    }\n  }\n\n  const runtime: TeamScheduler = {\n    async kickTeam(workspace, teamId, suppliedCaptain) {\n      const stateRoot = stateRootOf(workspace, config)\n      const team = await readTeam(stateRoot, teamId)\n      if (team === undefined || team.halted === true || team.phase === 'staged') return\n      const captain = liveCaptain(ctx, team.captainSessionId, suppliedCaptain)\n      if (captain === undefined) return\n      for (const member of team.members) {\n        if (member.status === 'removed') continue\n        await runtime.kickMember(workspace, teamId, member.name, captain)\n      }\n    },\n\n    async kickMember(workspace, teamId, memberName, suppliedCaptain) {\n      const stateRoot = stateRootOf(workspace, config)\n      const queueKey = memberQueueKey(stateRoot, teamId, memberName)\n      await serializeMember(queueKey, async () => {\n        let team = await readTeam(stateRoot, teamId)\n        if (team === undefined || team.halted === true || team.phase === 'staged') return\n        const captain = liveCaptain(ctx, team.captainSessionId, suppliedCaptain)\n        if (captain === undefined) return\n        let member = team.members.find(candidate => candidate.name === memberName && candidate.status !== 'removed')\n        if (member === undefined || !isMemberAvailable(ctx, member)) return\n\n        // A mailbox-only fallback is real pending work. Deliver it before a\n        // fresh task and acknowledge only after Harness accepts the follow-up.\n        const unread = await withTeamLock(teamLockKey(stateRoot, team.id), async () => {\n          const fresh = await readTeam(stateRoot, team!.id)\n          if (fresh === undefined) return []\n          const pending = await readPendingMailbox(stateRoot, fresh.id, member!.name)\n          await discardMailboxMessages(stateRoot, fresh.id, member!.name, pending.filter(message => !isCurrentMail(fresh, message)).map(message => message.id))\n          const current = pending.filter(message => isCurrentMail(fresh, message))\n          await claimMailboxDelivery(stateRoot, fresh.id, member!.name, current.map(message => message.id))\n          return current\n        })\n        if (unread.length > 0) {\n          const prompt = mailboxPrompt(team.id, member.name, unread)\n          const signal = new AbortController().signal\n          const accepted = config.dispatch === undefined\n            ? await deliverToMember(ctx, captain, member.id, prompt, signal, 'steer')\n            : await config.dispatch(captain, team.id, member.name, prompt, signal, 'steer')\n          if (accepted) {\n            await withTeamLock(teamLockKey(stateRoot, team.id), () => (\n              markMailboxDelivered(stateRoot, team!.id, member!.name, unread.map(message => message.id))\n            ))\n          } else {\n            await withTeamLock(teamLockKey(stateRoot, team.id), () => (\n              releaseMailboxDelivery(stateRoot, team!.id, member!.name, unread.map(message => message.id))\n            ))\n          }\n          return\n        }\n\n        const ticket = await withTeamLock(teamLockKey(stateRoot, team.id), async (): Promise<DispatchTicket | undefined> => {\n          const fresh = await readTeam(stateRoot, team!.id)\n          if (fresh === undefined || fresh.halted === true || fresh.phase === 'staged') return undefined\n          const currentMember = fresh.members.find(candidate => candidate.name === memberName && candidate.status !== 'removed')\n          if (currentMember === undefined || !isMemberAvailable(ctx, currentMember)) return undefined\n          const owned = ownedOpenTask(fresh.tasks, currentMember.name)\n          // An idle edge observed by this scheduler parks the exact open\n          // capability. Harness may dispose its AgentHandle after settlement,\n          // so registry absence is not evidence that the owner was lost. Keep\n          // the marker sticky across later kicks; only a durable attempt that\n          // this process has not observed is eligible for one cold recovery.\n          const parkedAttemptId = parkedAttempts.get(currentMember.id)\n          const recoverOwned = owned !== undefined\n            && (owned.attemptId === undefined || owned.attemptId !== parkedAttemptId)\n          const task = recoverOwned ? owned : owned === undefined\n            ? nextReadyTask(fresh.tasks, currentMember.name)\n            : undefined\n          if (task === undefined) {\n            if (currentMember.status !== 'idle') {\n              currentMember.status = 'idle'\n              await writeTeam(stateRoot, fresh)\n            }\n            return undefined\n          }\n          const previousAssignee = task.assignee\n          const previousStatus = recoverOwned ? task.status as 'claimed' | 'in_progress' : undefined\n          const previousAttempt = recoverOwned ? task.attempt : undefined\n          const previousAttemptId = recoverOwned ? task.attemptId : undefined\n          const previousResult = recoverOwned ? {\n            output: task.output, verdict: task.verdict, findings: task.findings,\n            changedPaths: task.changedPaths, acceptanceResults: task.acceptanceResults, commandsRun: task.commandsRun,\n          } : undefined\n          const attemptId = beginTaskAttempt(task, currentMember.name)\n          // A verdict must be able to say which revision was on disk when it\n          // started, so a review that runs while someone else edits the tree\n          // cannot later claim to have judged stable bytes (issue #161).\n          if (isVerdictKind(taskKindOf(task))) {\n            const scope = verdictScopePatterns(fresh, task)\n            if (scope.length > 0) task.verdictStartSnapshot = snapshotWorkspacePaths(workspace, scope)\n          }\n          // A recovered generation is parked before delivery. This makes each\n          // (member, attempt) recovery idempotent even if every status poll\n          // sees a disposed handle. Fresh pending work remains unparked so a\n          // genuinely lost first delivery can be recovered once.\n          if (recoverOwned) parkedAttempts.set(currentMember.id, attemptId)\n          else parkedAttempts.delete(currentMember.id)\n          currentMember.status = 'working'\n          await writeTeam(stateRoot, fresh)\n          const profileSeedId = taskProfileSeedId(task)\n          const protocol = teamProfileProtocol(fresh)\n          return {\n            taskId: task.id,\n            memberName: currentMember.name,\n            memberId: currentMember.id,\n            attempt: task.attempt ?? 1,\n            attemptId,\n            previousAssignee,\n            recoveredOwned: recoverOwned,\n            ...previousResult === undefined ? {} : { previousResult },\n            ...previousStatus === undefined ? {} : { previousStatus },\n            ...previousAttempt === undefined ? {} : { previousAttempt },\n            ...previousAttemptId === undefined ? {} : { previousAttemptId },\n            subject: task.subject,\n            description: task.description,\n            teamDescription: fresh.description,\n            ...protocol === undefined ? {} : { profileProtocol: protocol },\n            ...profileSeedId === undefined ? {} : { profileSeedId },\n            ...fresh.profile?.executionPrompt === undefined && config.executionPrompt === undefined\n              ? {}\n              : { executionPrompt: fresh.profile?.executionPrompt ?? config.executionPrompt },\n            kind: task.kind ?? 'work',\n            ...task.round === undefined ? {} : { round: task.round },\n            ...task.objective === undefined ? {} : { objective: task.objective },\n            ...task.inScope === undefined ? {} : { inScope: task.inScope },\n            ...task.outOfScope === undefined ? {} : { outOfScope: task.outOfScope },\n            ...task.acceptance === undefined ? {} : { acceptance: task.acceptance },\n            ...task.verify === undefined ? {} : { verify: task.verify },\n            ...task.reviewedTaskId === undefined ? {} : { reviewedTaskId: task.reviewedTaskId },\n            ...task.findingSourceTaskIds === undefined ? {} : { findingSourceTaskIds: task.findingSourceTaskIds },\n            dependencyOutputs: collectCompletedDependencyOutputs(\n              fresh.tasks,\n              task.id,\n              (message) => ctx.logger.warn(message),\n            ),\n          }\n        })\n        if (ticket === undefined) return\n\n        const taskForWarning = team.tasks.find((item) => item.id === ticket.taskId)\n        const workOrderStale = taskForWarning?.contractSnapshot === undefined\n          ? []\n          : contractStaleness(\n            taskForWarning,\n            digestWorkspacePaths(workspace, taskForWarning.contractSnapshot.artifacts.map((artifact) => artifact.path)),\n          )\n        const prompt = assignmentPrompt(ticket, config.stateDir, team.id, workOrderStale)\n        const signal = new AbortController().signal\n        const accepted = config.dispatch === undefined\n          ? await deliverToMember(ctx, captain, ticket.memberId, prompt, signal)\n          : await config.dispatch(captain, team.id, ticket.memberName, prompt, signal, 'queue', ticket.attemptId)\n        if (accepted) return\n\n        // Roll back only our exact failed dispatch. A concurrent captain\n        // handoff has already changed the capability and wins.\n        await withTeamLock(teamLockKey(stateRoot, team.id), async () => {\n          const fresh = await readTeam(stateRoot, team!.id)\n          if (fresh === undefined) return\n          const task = fresh.tasks.find(candidate => candidate.id === ticket.taskId)\n          if (task?.attemptId !== ticket.attemptId) return\n          if (ticket.recoveredOwned && ticket.previousStatus !== undefined && ticket.previousAttemptId !== undefined) {\n            // Recovery delivery failed. Restore the durable generation instead\n            // of returning it to pending, then keep it parked so later status\n            // kicks cannot spend an unbounded sequence of fresh attempts.\n            task.status = ticket.previousStatus\n            task.assignee = ticket.previousAssignee\n            task.attempt = ticket.previousAttempt\n            task.attemptId = ticket.previousAttemptId\n            Object.assign(task, ticket.previousResult)\n            parkedAttempts.set(ticket.memberId, ticket.previousAttemptId)\n          } else {\n            task.status = 'pending'\n            task.assignee = ticket.previousAssignee\n            task.attemptId = undefined\n            parkedAttempts.delete(ticket.memberId)\n          }\n          task.handoffId = undefined\n          task.reassigning = false\n          task.updatedAt = Date.now()\n          const currentMember = fresh.members.find(candidate => candidate.name === ticket.memberName)\n          if (currentMember !== undefined && currentMember.status !== 'removed') currentMember.status = 'idle'\n          await writeTeam(stateRoot, fresh)\n        })\n      })\n    },\n  }\n\n  const syncMemberStatus = async (agent: Agent, status: AgentStatus): Promise<void> => {\n    const workspace = agent.session.header.cwd ?? process.cwd()\n    const stateRoot = stateRootOf(workspace, config)\n    const located = await findTeamByParticipant(stateRoot, agent.id)\n    if (located === undefined) {\n      parkedAttempts.delete(agent.id)\n      return\n    }\n    if (located.captainSessionId === agent.id) {\n      // Captain takeover is scoped to the captain's current turn. Unlike a\n      // durable member, the captain has no scheduler lane that can resume an\n      // abandoned attempt later. Returning unfinished captain-owned work to\n      // the shared pool on the idle edge prevents it from becoming a\n      // permanently parked `claimed` task after the captain answers, is\n      // interrupted, or the user switches conversations.\n      if (status === 'running') return\n      let requeued = false\n      await withTeamLock(teamLockKey(stateRoot, located.id), async () => {\n        const fresh = await readTeam(stateRoot, located.id)\n        if (fresh === undefined || fresh.captainSessionId !== agent.id) return\n        for (const task of fresh.tasks) {\n          if (task.assignee !== CAPTAIN_KEY\n            || task.status === 'completed'\n            || task.status === 'failed'\n            || task.status === 'cancelled') continue\n          invalidateTaskAttempt(task)\n          task.reassigning = false\n          requeued = true\n        }\n        if (requeued) await writeTeam(stateRoot, fresh)\n      })\n      if (requeued) await runtime.kickTeam(workspace, located.id, agent)\n      return\n    }\n    const member = located.members.find(candidate => candidate.id === agent.id && candidate.status !== 'removed')\n    if (member === undefined) {\n      parkedAttempts.delete(agent.id)\n      return\n    }\n    await withTeamLock(teamLockKey(stateRoot, located.id), async () => {\n      const fresh = await readTeam(stateRoot, located.id)\n      const current = fresh?.members.find(candidate => candidate.id === agent.id && candidate.status !== 'removed')\n      if (fresh === undefined || current === undefined) return\n      const next = status === 'running' ? 'working' : 'idle'\n      if (next === 'idle') {\n        const owned = ownedOpenTask(fresh.tasks, current.name)\n        if (owned?.attemptId === undefined) parkedAttempts.delete(agent.id)\n        else parkedAttempts.set(agent.id, owned.attemptId)\n      } else {\n        parkedAttempts.delete(agent.id)\n      }\n      if (current.status === next) return\n      current.status = next\n      await writeTeam(stateRoot, fresh)\n    })\n    if (status === 'idle') await runtime.kickMember(workspace, located.id, member.name)\n  }\n\n  ctx.on('agent/status', ({ agent, status }) => {\n    void syncMemberStatus(agent, status).catch((error: unknown) => {\n      ctx.logger.warn(`agent-teams: member status scheduling failed for ${agent.id}: ${String(error)}`)\n    })\n  })\n\n  return runtime\n}\n"
    },
    {
      "path": "src/state.ts",
      "content": "/**\n * Team state persistence and pure team-logic rules.\n *\n * State lives on disk under `<workspace>/<stateDir>/<teamId>/`:\n * - `team.json` — the durable {@link TeamState} record\n * - `inbox/<agentKey>.jsonl` — one JSONL mailbox per agent (`captain` or a\n *   member name), mirroring the Claude Code AgentTeams mailbox layout\n *\n * All mutations run through an in-process per-team queue so read-modify-write\n * stays serial; `fs/promises` is used directly because the plugin owns this\n * bookkeeping (host-plane state, like session persistence) and the abstract\n * `fs` service offers no directory deletion.\n * @module dsh-agent-teams/state\n */\n\nimport { createHash, randomUUID } from 'node:crypto'\nimport { readFileSync } from 'node:fs'\nimport { mkdir, readFile, readdir, rename, rm, writeFile } from 'node:fs/promises'\nimport { join } from 'node:path'\nimport type { MemberToolFilter } from './tool-policies.ts'\nimport { FINDING_SEVERITIES, REVIEW_VERDICTS, TASK_KINDS, TERMINAL_TASK_STATUSES, type ReviewFinding, type TaskStatus, type TeamMember, type TeamMessage, type TeamProfileSnapshot, type TeamState, type TeamTask } from './types.ts'\nimport { hasValidQualityTaskFields, isReviewPolicy, isValidFindingLine, normalizeBlankOptionalTaskFields } from './quality-gates.ts'\nimport { teamLeadMatch, type LeadIdentity } from './lineage.ts'\n\nexport {\n  amendTaskContract,\n  buildCoverageMatrix,\n  canDeclareDelivery,\n  classifyChangedPath,\n  collectChangedPaths,\n  defaultQualityDeliveryGraph,\n  describeQualityLoop,\n  evaluateQualityCompletion,\n  hasValidQualityTaskFields,\n  isQualityKind,\n  isTaskRevision,\n  isValidFindingLine,\n  normalizeBlankOptionalTaskFields,\n  normalizeSentinelNumericTaskFields,\n  pathMatchesScope,\n  planQualityFollowUp,\n  qualityPlanningPrompt,\n  resumeTeamState,\n  sanitizeReviewAcceptance,\n  sanitizeReviewObjective,\n  taskKindOf,\n  validateCreateTask,\n} from './quality-gates.ts'\nexport type { ContractAmendmentInput } from './quality-gates.ts'\n\n/** Mailbox key of the captain. */\nexport const CAPTAIN_KEY = 'captain'\n/** A crashed live-delivery attempt becomes retryable after this interval. */\nconst MAILBOX_DELIVERY_LEASE_MS = 60_000\n/** Durable deny-list for AgentTeams members that must never be resumed. */\nconst RETIRED_MEMBERS_FILE = 'retired-members.json'\n\n/** In-process per-team mutation queues (promise chains). */\nconst locks = new Map<string, Promise<unknown>>()\n\n/**\n * Serialize mutations of one team across the whole process.\n * @param key - the team id (or any mutation scope).\n * @param fn - the mutation to run exclusively.\n * @returns the mutation's result.\n */\nexport async function withTeamLock<T>(key: string, fn: () => Promise<T>): Promise<T> {\n  const previous = locks.get(key) ?? Promise.resolve()\n  let release!: () => void\n  const gate = new Promise<void>((resolve) => { release = resolve })\n  const tail = previous.then(() => gate)\n  locks.set(key, tail)\n  await previous\n  try {\n    return await fn()\n  } finally {\n    release()\n    // Drop this key's queue entry once we are still its tail, so settled\n    // teams do not leave one resolved promise chained forever (the same\n    // cleanup discipline as the scheduler's serializeMember). A successor\n    // that already appended itself owns the map slot; keep its entry.\n    if (locks.get(key) === tail) locks.delete(key)\n  }\n}\n\n/**\n * Keys with an in-process lock queue (held or waiting), snapshot for\n * diagnostics and leak checks. The queue promises themselves stay private.\n */\nexport function teamLockQueueKeys(): readonly string[] {\n  return [...locks.keys()]\n}\n\n/** Longest key emitted before truncating and appending a digest. */\nconst MAX_KEY_LENGTH = 48\n\n/** Short stable digest, used to keep otherwise-colliding keys distinct. */\nfunction keyDigest(name: string): string {\n  return createHash('sha256').update(name).digest('hex').slice(0, 8)\n}\n\n/**\n * Fold a free-form name into a safe path/key segment.\n *\n * Unicode letters and digits survive, so CJK/Cyrillic/Greek names stay\n * distinct and readable; everything else — spaces, punctuation, path\n * separators, control characters — folds to `-`. An ASCII-only whitelist\n * mapped *every* non-Latin name onto one shared fallback, which silently\n * merged their mailboxes and rejected the second such member as a duplicate.\n *\n * A name with no letters or digits at all (pure emoji or punctuation) cannot\n * yield a readable key, so it gets a digest rather than a shared constant.\n * Over-long names are truncated with a digest appended, so names sharing a\n * long prefix stay distinct and the result stays within filesystem limits\n * (CJK costs 3 bytes per character in UTF-8).\n *\n * @param name - any user-supplied name.\n * @returns a non-empty key safe as a single path segment.\n */\nexport function sanitizeKey(name: string): string {\n  const cleaned = name.normalize('NFC').trim().toLowerCase()\n    .replace(/[^\\p{L}\\p{N}]+/gu, '-')\n    .replace(/^-+|-+$/g, '')\n  if (cleaned === '') return `k-${keyDigest(name)}`\n  const points = [...cleaned]\n  if (points.length > MAX_KEY_LENGTH) {\n    return `${points.slice(0, MAX_KEY_LENGTH).join('')}-${keyDigest(name)}`\n  }\n  return cleaned\n}\n\n/**\n * Whether `dependencies` are all satisfied (every named task exists and\n * completed) for the given task list.\n * @param tasks - the team's tasks.\n * @param dependencies - task ids the candidate depends on.\n * @returns the ids that are still unsatisfied, empty when claimable.\n */\nexport function unsatisfiedDependencies(tasks: TeamTask[], dependencies: string[]): string[] {\n  const byId = new Map(tasks.map((task) => [task.id, task]))\n  return dependencies.filter((id) => byId.get(id)?.status !== 'completed')\n}\n\n/**\n * The allowed task status transitions, keyed by current status.\n * Terminal statuses have no outgoing transitions.\n */\nexport const TASK_TRANSITIONS: Readonly<Record<TaskStatus, readonly TaskStatus[]>> = {\n  pending: ['claimed', 'cancelled'],\n  claimed: ['in_progress', 'failed', 'cancelled'],\n  in_progress: ['completed', 'failed', 'cancelled'],\n  completed: [],\n  failed: [],\n  cancelled: [],\n}\n\n/**\n * Validate one task status transition.\n * @param current - the task's current status.\n * @param next - the requested status.\n * @returns the transition error, or undefined when allowed.\n */\nexport function transitionError(current: TaskStatus, next: TaskStatus): string | undefined {\n  if (current === next) return undefined\n  if (!TASK_TRANSITIONS[current].includes(next)) {\n    return `task status cannot move from \"${current}\" to \"${next}\"`\n  }\n  return undefined\n}\n\n/** Execution results belong to one attempt; a retry must produce its own evidence. */\nfunction clearAttemptResult(task: TeamTask): void {\n  task.output = undefined\n  task.verdict = undefined\n  task.findings = undefined\n  task.changedPaths = undefined\n  task.acceptanceResults = undefined\n  task.commandsRun = undefined\n}\n\n/** Activate the task's current generation for one owner and return its capability id. */\nexport function activateTaskAttempt(task: TeamTask, assignee: string): string {\n  const attemptId = randomUUID()\n  task.status = 'claimed'\n  task.assignee = assignee\n  task.attemptId = attemptId\n  task.handoffId = undefined\n  task.reassigning = false\n  clearAttemptResult(task)\n  task.updatedAt = Date.now()\n  return attemptId\n}\n\n/** Start a fresh task generation for one owner. */\nexport function beginTaskAttempt(task: TeamTask, assignee: string): string {\n  task.attempt = (task.attempt ?? 0) + 1\n  return activateTaskAttempt(task, assignee)\n}\n\n/**\n * Revoke the current worker immediately. Clearing its capability makes old\n * updates stale; a separate handoff generation serializes async quiescence.\n */\n/** Cancel one unfinished task without returning it to the ready pool. */\nexport function cancelUnfinishedTask(task: TeamTask, output?: string): void {\n  if (TERMINAL_TASK_STATUSES.includes(task.status)) return\n  task.status = 'cancelled'\n  task.attemptId = undefined\n  task.handoffId = undefined\n  task.reassigning = false\n  if (output !== undefined) task.output = output\n  task.updatedAt = Date.now()\n}\n\nexport function invalidateTaskAttempt(\n  task: TeamTask,\n  nextAssignee?: string,\n  reassigning = false,\n): void {\n  task.attemptId = undefined\n  task.handoffId = randomUUID()\n  task.status = 'pending'\n  task.assignee = nextAssignee\n  task.reassigning = reassigning\n  clearAttemptResult(task)\n  task.updatedAt = Date.now()\n}\n\n/**\n * Create the team directory structure and the initial team record.\n * @param stateRoot - resolved absolute state root directory.\n * @param state - the initial team record.\n */\nexport async function createTeamDir(stateRoot: string, state: TeamState): Promise<void> {\n  const dir = join(stateRoot, state.id)\n  await mkdir(join(dir, 'inbox'), { recursive: true })\n  await atomicWriteText(join(dir, 'team.json'), JSON.stringify(state, null, 2))\n}\n\n/**\n * Read one team record; `undefined` when absent.\n * @param stateRoot - resolved absolute state root directory.\n * @param teamId - the team's sanitized id.\n */\nexport async function readTeam(stateRoot: string, teamId: string): Promise<TeamState | undefined> {\n  try {\n    const raw = await readFile(join(stateRoot, teamId, 'team.json'), 'utf8')\n    const value: unknown = JSON.parse(stripLeadingBom(raw))\n    const team = coerceTeamState(value, teamId)\n    if (team === undefined) {\n      throw new Error(`invalid AgentTeams state in team \"${teamId}\": ${describeTeamStateDefect(value, teamId)}`)\n    }\n    return team\n  } catch (error: unknown) {\n    if (error instanceof Error && 'code' in error && (error as NodeJS.ErrnoException).code === 'ENOENT') {\n      return undefined\n    }\n    throw error\n  }\n}\n\n/**\n * Synchronously read one team record while a continuable child is being\n * composed. Harness requires child setup contributions to be synchronous;\n * this narrow boundary lets a cold-resumed member restore its durable model\n * selection before its first request can be published.\n * @param stateRoot - resolved absolute state root directory.\n * @param teamId - the team's sanitized id.\n * @returns the team record, or `undefined` when absent.\n */\nexport function readTeamSync(stateRoot: string, teamId: string): TeamState | undefined {\n  try {\n    const raw = readFileSync(join(stateRoot, teamId, 'team.json'), 'utf8')\n    const value: unknown = JSON.parse(stripLeadingBom(raw))\n    const team = coerceTeamState(value, teamId)\n    if (team === undefined) {\n      throw new Error(`invalid AgentTeams state in team \"${teamId}\": ${describeTeamStateDefect(value, teamId)}`)\n    }\n    return team\n  } catch (error: unknown) {\n    if (error instanceof Error && 'code' in error && (error as NodeJS.ErrnoException).code === 'ENOENT') {\n      return undefined\n    }\n    throw error\n  }\n}\n\n/**\n * Persist one team record (inside the caller's lock).\n * @param stateRoot - resolved absolute state root directory.\n * @param state - the record to persist.\n */\nexport async function writeTeam(stateRoot: string, state: TeamState): Promise<void> {\n  await atomicWriteText(join(stateRoot, state.id, 'team.json'), JSON.stringify(state, null, 2))\n}\n\n/** Read the durable set of member session ids retired by remove/delete. */\nfunction parseRetiredMemberIds(raw: string): Set<string> {\n  const parsed: unknown = JSON.parse(stripLeadingBom(raw))\n  if (!Array.isArray(parsed) || parsed.some(value => typeof value !== 'string' || value === '')) {\n    throw new Error('invalid AgentTeams retired member index')\n  }\n  return new Set(parsed)\n}\n\n/** Synchronous role hydration before the host's first prompt assembly. */\nexport function readRetiredMemberIdsSync(stateRoot: string): Set<string> {\n  try { return parseRetiredMemberIds(readFileSync(join(stateRoot, RETIRED_MEMBERS_FILE), 'utf8')) } catch (error) {\n    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return new Set()\n    throw error\n  }\n}\n\nexport async function readRetiredMemberIds(stateRoot: string): Promise<Set<string>> {\n  try {\n    return parseRetiredMemberIds(await readFile(join(stateRoot, RETIRED_MEMBERS_FILE), 'utf8'))\n  } catch (error: unknown) {\n    if (error instanceof Error && 'code' in error && (error as NodeJS.ErrnoException).code === 'ENOENT') {\n      return new Set()\n    }\n    throw error\n  }\n}\n\n/** Atomically add session ids to the durable retired-member deny-list. */\nexport async function recordRetiredMemberIds(stateRoot: string, memberIds: readonly string[]): Promise<void> {\n  const additions = memberIds.filter(id => id !== '')\n  if (additions.length === 0) return\n  await withTeamLock(`retired-members:${stateRoot}`, async () => {\n    const retired = await readRetiredMemberIds(stateRoot)\n    for (const id of additions) retired.add(id)\n    await mkdir(stateRoot, { recursive: true })\n    await atomicWriteText(\n      join(stateRoot, RETIRED_MEMBERS_FILE),\n      `${JSON.stringify([...retired].sort(), null, 2)}\\n`,\n    )\n  })\n}\n\n/**\n * Find the team owned by one captain session (at most one per captain).\n * @param stateRoot - resolved absolute state root directory.\n * @param captainSessionId - the owning session id.\n * @param lead - durable lead identity of the calling session, when it may lead\n *   through a fork chain; omitted keeps the exact-id contract.\n * @returns the team record, or undefined when the captain leads no team.\n */\nexport async function findTeamByCaptain(\n  stateRoot: string,\n  captainSessionId: string,\n  lead?: LeadIdentity,\n): Promise<TeamState | undefined> {\n  let entries\n  try {\n    entries = await readdir(stateRoot, { withFileTypes: true })\n  } catch (error: unknown) {\n    if (error instanceof Error && 'code' in error && (error as NodeJS.ErrnoException).code === 'ENOENT') {\n      return undefined\n    }\n    throw error\n  }\n  let found: TeamState | undefined\n  for (const entry of entries) {\n    if (!entry.isDirectory()) continue\n    const team = await readTeam(stateRoot, entry.name)\n    if (team !== undefined && (team.captainSessionId === captainSessionId\n      || (lead !== undefined && teamLeadMatch(team, lead)))) {\n      if (found !== undefined && found.id !== team.id) {\n        throw new Error(`captain session leads multiple active teams (\"${found.id}\", \"${team.id}\"); archive one before continuing`)\n      }\n      found = team\n    }\n  }\n  return found\n}\n\n/**\n * Find the team in which one session is an active participant.\n * Captains match `captainSessionId` — including a lead session that inherited\n * it through a fork — and members match their durable child session id.\n * Removed members no longer have access to team-scoped tools.\n * @param stateRoot - resolved absolute state root directory.\n * @param agentSessionId - calling captain/member session id.\n * @param lead - durable lead identity of the calling session, when available.\n * @returns the team record, or undefined when the caller belongs to no team.\n */\nexport async function findTeamByParticipant(\n  stateRoot: string,\n  agentSessionId: string,\n  lead?: LeadIdentity,\n): Promise<TeamState | undefined> {\n  let entries\n  try {\n    entries = await readdir(stateRoot, { withFileTypes: true })\n  } catch (error: unknown) {\n    if (error instanceof Error && 'code' in error && (error as NodeJS.ErrnoException).code === 'ENOENT') {\n      return undefined\n    }\n    throw error\n  }\n  let found: TeamState | undefined\n  for (const entry of entries) {\n    if (!entry.isDirectory()) continue\n    const team = await readTeam(stateRoot, entry.name)\n    const participates = team !== undefined && (team.captainSessionId === agentSessionId\n      || (lead !== undefined && teamLeadMatch(team, lead))\n      || team.members.some((member) => member.id === agentSessionId && member.status !== 'removed'))\n    if (participates && team !== undefined) {\n      if (found !== undefined && found.id !== team.id) {\n        throw new Error(`agent session belongs to multiple active teams (\"${found.id}\", \"${team.id}\"); the target team is ambiguous`)\n      }\n      found = team\n    }\n  }\n  return found\n}\n\n/** Build a fresh message record. */\nexport function createMessage(from: string, to: string, content: string): TeamMessage {\n  return { id: randomUUID(), from, to, content, ts: Date.now() }\n}\n\n/**\n * Append one message to an agent's mailbox (JSONL).\n * @param stateRoot - resolved absolute state root directory.\n * @param teamId - the team id.\n * @param agentKey - `captain` or a member name.\n * @param message - the message to append.\n */\nexport async function appendMailbox(\n  stateRoot: string,\n  teamId: string,\n  agentKey: string,\n  message: TeamMessage,\n): Promise<void> {\n  const file = join(stateRoot, teamId, 'inbox', `${sanitizeKey(agentKey)}.jsonl`)\n  await mkdir(join(stateRoot, teamId, 'inbox'), { recursive: true })\n  let existing = ''\n  try {\n    existing = await readFile(file, 'utf8')\n  } catch (error: unknown) {\n    if (!(error instanceof Error && 'code' in error && (error as NodeJS.ErrnoException).code === 'ENOENT')) {\n      throw error\n    }\n  }\n  const separator = existing !== '' && !existing.endsWith('\\n') ? '\\n' : ''\n  await atomicWriteText(file, `${existing}${separator}${JSON.stringify(message)}\\n`)\n}\n\n/**\n * Read one agent's whole mailbox, oldest first.\n * @param stateRoot - resolved absolute state root directory.\n * @param teamId - the team id.\n * @param agentKey - `captain` or a member name.\n * @param onMalformedLine - optional diagnostic hook; malformed records are\n * skipped so one manually damaged line cannot make the whole team unreadable.\n * @returns the messages, empty when the mailbox does not exist yet.\n */\nexport async function readMailbox(\n  stateRoot: string,\n  teamId: string,\n  agentKey: string,\n  onMalformedLine?: (lineNumber: number, error: unknown) => void,\n): Promise<TeamMessage[]> {\n  const file = join(stateRoot, teamId, 'inbox', `${sanitizeKey(agentKey)}.jsonl`)\n  try {\n    const raw = await readFile(file, 'utf8')\n    const messages: TeamMessage[] = []\n    for (const [index, rawLine] of raw.split('\\n').entries()) {\n      const line = stripLeadingBom(rawLine)\n      if (line.trim() === '') continue\n      let value: unknown\n      try {\n        value = JSON.parse(line)\n      } catch {\n        onMalformedLine?.(index + 1, new Error('invalid JSON'))\n        continue\n      }\n      if (!isTeamMessage(value)) {\n        onMalformedLine?.(index + 1, new Error('invalid message shape'))\n        continue\n      }\n      messages.push(value)\n    }\n    return messages\n  } catch (error: unknown) {\n    if (error instanceof Error && 'code' in error && (error as NodeJS.ErrnoException).code === 'ENOENT') {\n      return []\n    }\n    throw error\n  }\n}\n\n/** Read only messages that have not been acknowledged by their recipient. */\nexport async function readUnreadMailbox(\n  stateRoot: string,\n  teamId: string,\n  agentKey: string,\n  onMalformedLine?: (lineNumber: number, error: unknown) => void,\n): Promise<TeamMessage[]> {\n  return (await readMailbox(stateRoot, teamId, agentKey, onMalformedLine))\n    .filter(message => message.readAt === undefined && message.discardedAt === undefined)\n}\n\n/** Pending delivery is distinct from delivered-but-not-yet-read input. */\nexport async function readPendingMailbox(stateRoot: string, teamId: string, agentKey: string): Promise<TeamMessage[]> {\n  const now = Date.now()\n  return (await readUnreadMailbox(stateRoot, teamId, agentKey))\n    .filter(message => message.deliveredAt === undefined\n      && (message.deliveryClaimedAt === undefined\n        || now - message.deliveryClaimedAt >= MAILBOX_DELIVERY_LEASE_MS))\n}\n\nasync function mutateMailbox(\n  stateRoot: string,\n  teamId: string,\n  agentKey: string,\n  messageIds: readonly string[],\n  mutate: (message: TeamMessage) => TeamMessage,\n): Promise<void> {\n  if (messageIds.length === 0) return\n  const file = join(stateRoot, teamId, 'inbox', `${sanitizeKey(agentKey)}.jsonl`)\n  let raw: string\n  try {\n    raw = await readFile(file, 'utf8')\n  } catch (error: unknown) {\n    if (error instanceof Error && 'code' in error && (error as NodeJS.ErrnoException).code === 'ENOENT') return\n    throw error\n  }\n  const selected = new Set(messageIds)\n  const lines = raw.split('\\n').map((rawLine) => {\n    const line = stripLeadingBom(rawLine)\n    if (line.trim() === '') return rawLine\n    try {\n      const value: unknown = JSON.parse(line)\n      if (!isTeamMessage(value) || !selected.has(value.id)) return rawLine\n      return JSON.stringify(mutate(value))\n    } catch {\n      return rawLine\n    }\n  })\n  await atomicWriteText(file, lines.join('\\n'))\n}\n\n/** Lease selected fallback messages to one delivery path. */\nexport async function claimMailboxDelivery(\n  stateRoot: string,\n  teamId: string,\n  agentKey: string,\n  messageIds: readonly string[],\n): Promise<void> {\n  const now = Date.now()\n  await mutateMailbox(stateRoot, teamId, agentKey, messageIds, message => ({\n    ...message,\n    deliveryClaimedAt: now,\n  }))\n}\n\n/** Release a failed delivery lease so the scheduler can retry it later. */\nexport async function releaseMailboxDelivery(\n  stateRoot: string,\n  teamId: string,\n  agentKey: string,\n  messageIds: readonly string[],\n): Promise<void> {\n  await mutateMailbox(stateRoot, teamId, agentKey, messageIds, (message) => {\n    const { deliveryClaimedAt: _claimed, ...released } = message\n    return released\n  })\n}\n\n/**\n * Mark selected durable mailbox records delivered/read while preserving\n * malformed lines for diagnostics. Callers serialize this with the team lock.\n */\nexport async function acknowledgeMailbox(\n  stateRoot: string,\n  teamId: string,\n  agentKey: string,\n  messageIds: readonly string[],\n): Promise<void> {\n  const now = Date.now()\n  await mutateMailbox(stateRoot, teamId, agentKey, messageIds, (message) => {\n    const { deliveryClaimedAt: _claimed, ...rest } = message\n    return {\n      ...rest,\n      deliveredAt: message.deliveredAt ?? now,\n      readAt: message.readAt ?? now,\n    }\n  })\n}\n\n/** Acceptance by Harness is not evidence that a model step consumed input. */\nexport async function markMailboxDelivered(stateRoot: string, teamId: string, agentKey: string, ids: readonly string[]): Promise<void> {\n  await mutateMailbox(stateRoot, teamId, agentKey, ids, (message) => {\n    const { deliveryClaimedAt: _claimed, ...rest } = message\n    return { ...rest, deliveredAt: message.deliveredAt ?? Date.now() }\n  })\n}\n\nexport async function discardMailboxMessages(stateRoot: string, teamId: string, agentKey: string, ids: readonly string[]): Promise<void> {\n  await mutateMailbox(stateRoot, teamId, agentKey, ids, message => ({ ...message, discardedAt: message.discardedAt ?? Date.now() }))\n}\n\n/** Remove the optional UTF-8 BOM some editors prepend to JSON text. */\nfunction stripLeadingBom(value: string): string {\n  return value.charCodeAt(0) === 0xFEFF ? value.slice(1) : value\n}\n\n/** Rename attempts before falling back to a direct overwrite. */\nconst ATOMIC_RENAME_RETRIES = 3\n/** Pause between rename attempts, giving a briefly-locking owner time to finish. */\nconst ATOMIC_RENAME_RETRY_DELAY_MS = 50\n/**\n * Rename error codes worth retrying before the direct-write fallback. On\n * Windows, replacing an existing file whose target is momentarily held open\n * without FILE_SHARE_DELETE surfaces as EPERM (or EACCES/EBUSY variants);\n * EEXIST/ENOTEMPTY cover other \"target busy\" edge shapes.\n */\nconst RETRYABLE_RENAME_CODES = new Set(['EPERM', 'EACCES', 'EBUSY', 'EEXIST', 'ENOTEMPTY'])\n\nfunction isRetryableRenameError(error: unknown): boolean {\n  return error instanceof Error\n    && 'code' in error\n    && RETRYABLE_RENAME_CODES.has((error as NodeJS.ErrnoException).code ?? '')\n}\n\nfunction sleep(ms: number): Promise<void> {\n  return new Promise((resolve) => setTimeout(resolve, ms))\n}\n\n/** Filesystem primitives used by {@link replaceFileAtomicOrDirect}; injectable for tests. */\nexport interface AtomicReplacePrimitives {\n  rename: (from: string, to: string) => Promise<void>\n  writeFile: (file: string, content: string) => Promise<void>\n  remove: (file: string) => Promise<void>\n}\n\n/** Tuning knobs for {@link replaceFileAtomicOrDirect} (defaults match production). */\nexport interface AtomicReplaceOptions {\n  /** Rename attempts before the direct-write fallback (default 3). */\n  retries?: number\n  /** Delay between rename attempts in ms (default 50). */\n  retryDelayMs?: number\n}\n\n/**\n * Replace `file` with `content`, preferring an atomic same-directory rename of\n * an already-written temp file.\n *\n * On Windows, `rename(tmp, file)` over an existing target throws EPERM while\n * any other process keeps the target open without FILE_SHARE_DELETE (editors,\n * indexers, antivirus scans, preview panes). By that point the payload has\n * already been fully written to the temp file, so a direct overwrite of the\n * target is a content-equivalent degraded path: retry the rename a few times\n * (transient locks clear quickly), then write the target in place. Every path\n * removes the temp file; when both the atomic rename and the direct write\n * fail, the combined error surfaces as an {@link AggregateError}.\n *\n * @returns nothing once the file has been replaced by one of the two paths.\n */\nexport async function replaceFileAtomicOrDirect(\n  temporary: string,\n  file: string,\n  content: string,\n  primitives: AtomicReplacePrimitives,\n  options: AtomicReplaceOptions = {},\n): Promise<void> {\n  const retries = options.retries ??